    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüğü korunarak yapılıp yapılmadığı, ağ trafiği yakalanarak ve şifreleme protokolleri kontrol edilerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz veya zararlı girdilerin reddedilip reddedilmediği, çeşitli hata senaryoları ve enjeksiyon denemeleriyle test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve ayrıntılı logların yetkili personele gösterilip gösterilmediği, hata senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum süresi dolmadan uyarı gösterilmesi, taslak kaydı ve veri kaybı olmadan devam etme akışının, zamanlama senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığının ve bot eşiği aşıldığında etkileşimsiz kanıt veya nesne tanıma sorgusunun doğru sırayla istenip istenmediğinin, bot simülasyonlarıyla test edilmesi gerekir."
