      "title": "SMS code generation preserves failed count at lockout threshold boundary",
      "covers": [
        "KDH-024"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a failed authentication count equal to the maximum allowed before lockout (e.g., 4 out of 5).",
      "test_inputs": "Valid company representative credentials, valid phone number associated with the account.",
      "assumptions": "The lockout threshold is 5 failed attempts. The system allows SMS code generation at this boundary.",
      "steps": [
