{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Multiple authenticator failure threshold triggers full disablement",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with password and second-factor (e.g., TOTP) enabled. The account is not currently locked or disabled. The failure threshold defined in VBP SDD §14 is known (assumed to be 5 for this test).",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The failure threshold in VBP SDD §14 is 5 consecutive failed attempts. The system tracks failures per authenticator type and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with valid username, invalid password, and valid second-factor code.",
          "expected": "Authentication fails. Password failure count increments to 1."
        },
        {
          "no": 2,
          "action": "Attempt login with valid username, valid password, and invalid second-factor code.",
          "expected": "Authentication fails. Second-factor failure count increments to 1."
        },
        {
          "no": 3,
          "action": "Repeat the sequence of invalid password and invalid second-factor attempts until the total consecutive failed authentication attempts on the account reach the threshold (5 attempts total, involving both authenticators).",
          "expected": "The 5th failed attempt triggers the threshold condition."
        },
        {
          "no": 4,
          "action": "Check the status of the password authenticator for the account.",
          "expected": "The password authenticator is disabled."
        },
        {
          "no": 5,
          "action": "Check the status of the second-factor authenticator for the account.",
          "expected": "The second-factor authenticator is disabled."
        },
        {
          "no": 6,
          "action": "Attempt login with valid username, valid password, and valid second-factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Single authenticator failure does not disable other authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and second-factor enabled. The account is not currently locked or disabled. The failure threshold is 5.",
      "test_inputs": "Valid username, invalid password, valid second-factor code.",
      "assumptions": "The requirement specifies disabling 'all of the authenticators involved' in consecutive failed attempts that reach the threshold. If only one authenticator is involved in the failures, only that one should be affected, or the condition 'more than one authenticator is involved' is not met, so no disabling occurs per the specific clause. However, standard lockout might apply. This test verifies that if the condition 'more than one authenticator involved' is NOT met, the specific multi-authenticator disablement logic is not triggered.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login 5 times with valid username, invalid password, and valid second-factor code.",
          "expected": "Authentication fails 5 times. Only the password authenticator is involved in the failures."
        },
        {
          "no": 2,
          "action": "Check the status of the second-factor authenticator for the account.",
          "expected": "The second-factor authenticator remains enabled (not disabled by the multi-authenticator rule)."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Failure threshold not reached with multiple authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and second-factor enabled. The failure threshold is 5.",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The failure threshold in VBP SDD §14 is 5 consecutive failed attempts.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login 4 times with valid username, invalid password, and invalid second-factor code.",
          "expected": "Authentication fails 4 times. The threshold (5) is not reached."
        },
        {
          "no": 2,
          "action": "Check the status of the password authenticator.",
          "expected": "The password authenticator remains enabled."
        },
        {
          "no": 3,
          "action": "Check the status of the second-factor authenticator.",
          "expected": "The second-factor authenticator remains enabled."
        }
      ]
    }
  ]
}

